package patterns2;

public class AlphabetSquare {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char ch ='A';
		for(int k=0;k<=5;k++) {
			ch='A';
			for(int j=0;j<=5;j++) {
				System.out.print(ch++);
				
			}
			System.out.println();
		}
	}

}


